// AP Physics 1 Practice Exam 2: 42 multiple choice across all eight units, then MR, TBR, EDA, QQT (40 points).
import { graph, bars } from "../../plot.js";
import { scene, tank } from "../../diagrams.js";
const R = String.raw;
const one = (blocks, title = "") => [{ title, blocks }];
const SKILL = (t) => "u" + String(t).split(".")[0];
const mc = (n, topic, difficulty, o, choices, why) => ({ id: "e2-m" + String(n).padStart(2, "0"), type: "mcq", skill: SKILL(topic), topic, difficulty, ...o, choices, why, answer: 0 });

// ---------- graphs and diagrams ----------
const gokart = () => graph({ x: [0, 15], y: [0, 10], step: { x: 1, y: 2 }, labelEvery: 2, xname: "t (s)", yname: "v (m/s)", segments: [[0, 0, 4, 8], [4, 8, 10, 8], [10, 8, 14, 0]],
  alt: "Graph of the go-kart's velocity in meters per second versus time in seconds. The velocity rises in a straight line from 0 at 0 seconds to 8 at 4 seconds, stays at 8 until 10 seconds, then falls in a straight line to 0 at 14 seconds." });
const racerA = () => graph({ x: [0, 10], y: [-2, 3], step: { x: 1, y: 1 }, xname: "t (s)", yname: "a (m/s²)", segments: [[0, 2, 3, 2], [3, 0, 5, 0], [5, -1.5, 9, -1.5]],
  alt: "Graph of the racer's acceleration in meters per second squared versus time in seconds. The acceleration is 2.0 from 0 to 3 seconds, 0 from 3 to 5 seconds, and negative 1.5 from 5 to 9 seconds." });
const sofaF = () => graph({ x: [0, 200], y: [0, 175], step: { x: 50, y: 25 }, labelEvery: 1, xname: "Push (N)", yname: "Friction (N)", segments: [[0, 0, 150, 150], [150, 100, 200, 100]], dots: [[150, 150, "closed"], [150, 100, "closed"]],
  alt: "Graph of the friction force on the sofa in newtons versus the applied push in newtons. The friction force equals the push, rising in a straight line from 0 to 150 newtons at a push of 150 newtons. For pushes above 150 newtons the friction force is constant at 100 newtons." });
const parcelFx = () => graph({ x: [0, 8], y: [-8, 8], step: { x: 1, y: 2 }, xname: "x (m)", yname: "F (N)", segments: [[0, 0, 2, 6], [2, 6, 5, 6], [5, 6, 7, -6]],
  alt: "Graph of the force component along the line in newtons versus position in meters. The force rises in a straight line from 0 at 0 meters to 6 newtons at 2 meters, stays at 6 newtons until 5 meters, then falls in a straight line to negative 6 newtons at 7 meters." });
const soapBars = () => bars({ labels: ["Kinetic", "Gravitational", "Thermal"], series: [{ name: "Point 1", values: [6, 2, 0] }, { name: "Point 2", values: [3, 3, null] }], y: [0, 8], step: 2, yname: "Energy (J)", width: 420, height: 260,
  alt: "Bar chart of energy in joules at two points. At point 1, kinetic energy is 6, gravitational potential energy is 2, and thermal energy is 0. At point 2, kinetic energy is 3 and gravitational potential energy is 3. No thermal energy bar is shown for point 2." });
const scooterW = () => graph({ x: [0, 11], y: [0, 420], step: { x: 1, y: 60 }, labelEvery: 1, xname: "t (s)", yname: "W (J)", segments: [[0, 0, 4, 240], [4, 240, 10, 384]],
  alt: "Graph of the total work done by the motor in joules versus time in seconds. The work rises in a straight line from 0 at 0 seconds to 240 at 4 seconds, then rises more gently in a straight line to 384 at 10 seconds." });
const golfF = () => graph({ x: [0, 1.2], y: [0, 2], step: { x: 0.2, y: 0.5 }, xname: "t (ms)", yname: "F (kN)", segments: [[0, 0, 0.4, 1.8], [0.4, 1.8, 1, 0]],
  alt: "Graph of the force of the club on the ball in kilonewtons versus time in milliseconds. The force rises in a straight line from 0 at 0 milliseconds to 1.8 at 0.4 milliseconds, then falls in a straight line to 0 at 1.0 millisecond." });
const lazyW = () => graph({ x: [0, 11], y: [0, 8], step: { x: 1, y: 2 }, xname: "t (s)", yname: "ω (rad/s)", segments: [[0, 0, 3, 6], [3, 6, 8, 6], [8, 6, 10, 0]],
  alt: "Graph of the angular speed in radians per second versus time in seconds. The angular speed rises in a straight line from 0 at 0 seconds to 6 at 3 seconds, stays at 6 until 8 seconds, then falls in a straight line to 0 at 10 seconds." });
const buoyX = () => graph({ x: [0, 8], y: [-0.6, 0.6], step: { x: 1, y: 0.5 }, xname: "t (s)", yname: "x (m)", fns: [{ f: (t) => 0.5 * Math.sin((Math.PI * t) / 2), from: 0, to: 8 }],
  alt: "Graph of the buoy's position in meters versus time in seconds. The curve is a sine wave starting at 0 at 0 seconds, reaching a maximum of 0.50 at 1 second, returning to 0 at 2 seconds, reaching negative 0.50 at 3 seconds, and repeating with a period of 4 seconds." });

const planterDiagram = () => scene({ width: 300, height: 240, alt: "A planter of mass m hangs from a ceiling by a light cord. The cord slants down and to the right, making an angle theta with a dashed vertical line through its top end. A horizontal arrow labeled F points to the right from the planter.", items: [
  { ground: { from: [260, 215], to: [40, 215] } }, { line: { from: [100, 215], to: [100, 60], dash: true } }, { line: { from: [100, 215], to: [150, 105] } },
  { arc: { x: 100, y: 215, r: 55, from: -90, to: -65.6, label: "θ" } }, { circle: { x: 150, y: 90, r: 16, label: "m" } },
  { arrow: { from: [168, 90], to: [250, 90], kind: "force", label: "F", dy: 16 } }] });
const chuteDiagram = () => {
  const pts = [];
  for (let t = 0; t <= 90; t += 10) pts.push([160 - 100 * Math.cos((t * Math.PI) / 180), 140 - 100 * Math.sin((t * Math.PI) / 180)]);
  pts.push([160, 40], [60, 40]);
  return scene({ width: 470, height: 200, alt: "A smooth curved chute descends from a height h on the left to a level floor. A parcel of mass m sits at the top of the chute. The floor to the right of the chute has a rough section of length L, then a smooth section ending at a wall, where a spring of spring constant k is attached.", items: [
    { poly: { points: pts } }, { ground: { from: [20, 40], to: [450, 40] } }, { rect: { x: 70, y: 152, w: 26, h: 20, rot: -8, label: "m" } },
    { line: { from: [30, 40], to: [30, 140], dash: true } }, { label: { x: 24, y: 90, text: "h", anchor: "end" } },
    { poly: { points: [[160, 40], [300, 40], [300, 46], [160, 46]] } }, { label: { x: 230, y: 62, text: "rough, μ" } },
    { line: { from: [160, 24], to: [300, 24] } }, { label: { x: 230, y: 10, text: "L" } },
    { line: { from: [440, 40], to: [440, 110] } }, { spring: { from: [440, 60], to: [360, 60], coils: 8, amp: 8, label: "k" } }] });
};
